<script setup lang="ts">
import OperatorIcon from "./OperatorIcon.vue";
import { computed, ref } from "vue";
import { brokerMoney, decimalUnits, holdingValues, type BrokerObservation, type BrokerSync } from "../operations/broker-holdings";
import StrategyMonitor from "./StrategyMonitor.vue";
const props = defineProps<{ observation: BrokerObservation | null; sync: BrokerSync; error: string; loading: boolean; now: number }>();
defineEmits<{ refresh: []; connect: [] }>();
const selected = ref("");
const search = ref("");
const age = computed(() => props.observation ? Math.max(0, props.now - props.observation.observed_ms) : 0);
function elapsed(ms: number): string { return ms < 60_000 ? `${Math.floor(ms / 1000)}s` : ms < 3_600_000 ? `${Math.floor(ms / 60_000)}m` : `${Math.floor(ms / 3_600_000)}h`; }
const stale = computed(() => !props.observation || age.value > 60_000 || Boolean(props.error));
const connected = computed(() => ["connected", "syncing"].includes(props.sync.state) && !!props.sync.last_success_ms);
const busy = computed(() => ["syncing", "authorizing"].includes(props.sync.state));
const status = computed(() => props.sync.state === "authorizing" ? "Awaiting authorization" : props.sync.state === "syncing" ? "Syncing account" : connected.value ? (stale.value ? "Account delayed" : "Account synced") : props.sync.state === "degraded" ? "Sync interrupted" : "Connection needed");
const observedAt = computed(() => props.observation ? new Date(props.observation.observed_ms).toISOString() : "");
const observedLabel = computed(() => observedAt.value ? new Intl.DateTimeFormat(undefined, { dateStyle: "medium", timeStyle: "medium" }).format(new Date(observedAt.value)) : "Never");
const rows = computed(() => (props.observation?.positions ?? []).map(position => ({ ...position, ...holdingValues(position, props.observation?.quotes ?? []) })));
const filtered = computed(() => rows.value.filter(row => row.asset.toLowerCase().includes(search.value.toLowerCase())));
const detail = computed(() => rows.value.find(row => row.asset === selected.value) ?? rows.value[0]);
const permissions = computed(() => props.sync.account_permissions && props.now - props.sync.account_permissions.observed_ms <= 60_000 ? props.sync.account_permissions : undefined);
const tradeUrl = computed(() => detail.value ? `https://robinhood.com/us/en/crypto/${encodeURIComponent(detail.value.asset.toLowerCase())}/` : 'https://robinhood.com/');
const allocation = computed(() => {
  const portfolio = props.observation?.portfolio;
  if (!portfolio) return null;
  const crypto = decimalUnits(portfolio.crypto_value), cash = decimalUnits(portfolio.cash);
  if (crypto < 0n || cash < 0n || crypto + cash === 0n) return null;
  const cryptoPercent = Number(crypto * 1000n / (crypto + cash)) / 10;
  return { crypto: cryptoPercent, cash: Math.round((100 - cryptoPercent) * 10) / 10 };
});
const nextRead = computed(() => props.sync.next_poll_ms ? elapsed(Math.max(0, props.sync.next_poll_ms - props.now)) : null);
const money = (value: string | null | undefined) => value == null ? '—' : brokerMoney(value);
const pnlClass = (value: string | null) => value === null ? '' : decimalUnits(value) < 0n ? 'negative' : decimalUnits(value) > 0n ? 'positive' : '';
</script>

<template>
  <section class="broker-holdings" aria-labelledby="broker-holdings-heading">
    <header class="account-heading">
      <div class="account-identity"><span class="account-icon" aria-hidden="true"><OperatorIcon name="positions" /></span><div><h2 id="broker-holdings-heading">Robinhood holdings <span>{{ observation?.account.crypto ?? '' }}</span></h2></div></div>
      <div class="account-actions"><span class="connection-status" :data-ok="connected && !stale"><i></i>{{ status }}</span><button class="refresh-button" :disabled="busy || !connected" @click="$emit('refresh')" :title="connected ? 'Request current holdings and prices from Robinhood' : 'Connect Robinhood to enable account refresh'"><OperatorIcon name="refresh" /> {{ busy ? 'Syncing…' : 'Refresh' }}</button></div>
    </header>
    <div v-if="!connected || error" class="connection-notice" role="status">
      <span class="notice-icon" aria-hidden="true">↗</span><div><strong>{{ error ? 'Account update unavailable' : sync.state === 'authorizing' ? 'Finish connecting Robinhood' : 'Connect for automatic account updates' }}</strong><p>{{ error || (sync.state === 'authorizing' ? 'Authorize Helios in Robinhood. Your holdings will appear here automatically.' : 'A direct connection keeps balances, positions and prices current, including when this chat is closed.') }}</p></div>
      <a v-if="sync.authorization_url" :href="sync.authorization_url" target="_blank" rel="noopener noreferrer">Continue to Robinhood ↗</a>
      <button v-else :disabled="busy || sync.state === 'offline'" @click="$emit('connect')">{{ busy ? 'Connecting…' : 'Connect Robinhood' }}</button>
    </div>
    <template v-if="observation">
      <div class="account-overview">
        <div class="portfolio-value">
          <span class="eyebrow">Account value <span v-if="stale" class="aging">Last known</span></span>
          <div class="total-value">{{ money(observation.portfolio.total_value) }}<span>USD</span></div>
          <div v-if="allocation" class="allocation" aria-label="Crypto and cash allocation">
            <div class="allocation-track" aria-hidden="true"><span :style="{ width: `${allocation.crypto}%` }"></span></div>
            <div class="allocation-labels"><span><i></i>Crypto <strong>{{ allocation.crypto.toFixed(1) }}%</strong></span><span><i></i>Cash <strong>{{ allocation.cash.toFixed(1) }}%</strong></span></div>
          </div>
          <span v-else class="allocation-unavailable">Allocation unavailable</span>
        </div>
        <div class="account-metrics">
          <div class="metric"><span>Crypto value</span><strong>{{ money(observation.portfolio.crypto_value) }}</strong><small>{{ observation.positions.length }} {{ observation.positions.length === 1 ? 'holding' : 'holdings' }}</small></div>
          <div class="metric"><span>Available cash</span><strong>{{ money(observation.portfolio.cash) }}</strong><small>Uninvested balance</small></div>
          <div class="metric"><span>Buying power</span><strong>{{ money(observation.portfolio.crypto_buying_power) }}</strong><small>{{ observation.portfolio.crypto_buying_power === null ? 'Not supplied by broker' : 'Available for crypto' }}</small></div>
        </div>
      </div>
      <div class="portfolio-grid">
        <div class="position-register">
          <div class="register-heading"><div><h3>Open positions <span>{{ rows.length }}</span></h3></div><label class="asset-search"><OperatorIcon name="search" /><input v-model="search" aria-label="Filter holdings" placeholder="Filter assets" /></label></div>
          <div class="broker-table-scroll" tabindex="0" aria-label="Robinhood holdings. Scroll horizontally for quantities."><table aria-label="Open crypto positions"><thead><tr><th scope="col">Instrument</th><th scope="col" class="number">Quantity</th><th scope="col" class="number">Avg. cost</th><th scope="col" class="number">Mark</th><th scope="col" class="number">Market value</th><th scope="col" class="number">Price P&amp;L</th></tr></thead><tbody>
            <tr v-for="row in filtered" :key="row.asset" :class="{ selected: detail?.asset === row.asset }"><th scope="row"><button class="asset-button" :aria-pressed="detail?.asset === row.asset" @click="selected = row.asset"><span class="asset-icon">{{ row.asset.slice(0, 3) }}</span><span><strong>{{ row.asset }}</strong><small class="asset-pair">{{ row.asset }} / USD</small><small class="compact-quantity">{{ row.quantity }}</small></span></button></th><td class="number">{{ row.quantity }} <span class="sr-only">{{ row.asset }}</span></td><td class="number">{{ money(row.average) }}</td><td class="number"><span>{{ money(row.mark) }}</span><small v-if="row.quote" :class="{ 'old-quote': now - row.quote.quoted_ms > 60_000 }">{{ elapsed(Math.max(0, now - row.quote.quoted_ms)) }} ago</small></td><td class="number value-cell">{{ money(row.value) }}</td><td class="number" :class="pnlClass(row.pnl)">{{ row.pnl !== null && decimalUnits(row.pnl) > 0n ? '+' : '' }}{{ money(row.pnl) }}</td></tr>
            <tr v-if="rows.length === 0"><td colspan="6" class="empty-account">Robinhood reported no crypto holdings at this account read.</td></tr><tr v-else-if="!filtered.length"><td colspan="6" class="empty-account">No assets match your filter.</td></tr>
          </tbody></table></div>
          <footer class="register-footer"><span>Price P&amp;L excludes trading fees.</span><span>{{ observation.open_order_count }} open {{ observation.open_order_count === 1 ? 'order' : 'orders' }}</span></footer>
        </div>
        <div class="book-monitor"><StrategyMonitor :sync="sync" :now="now" /></div>
        <aside class="position-detail" aria-label="Selected holding details">
          <template v-if="detail"><div class="detail-title"><span class="eyebrow">Position detail</span><h3>{{ detail.asset }} <span>/ USD</span></h3><div class="detail-valuation"><strong>{{ money(detail.value) }}</strong><span :class="pnlClass(detail.pnl)">{{ detail.pnl !== null && decimalUnits(detail.pnl) > 0n ? '+' : '' }}{{ money(detail.pnl) }} <small>price P&amp;L</small></span></div></div>
            <div class="exit-state"><strong>Manual position</strong><p>No automated exit</p></div>
            <a class="trade-link" :href="tradeUrl" target="_blank" rel="noopener noreferrer">Trade {{ detail.asset }} at Robinhood <OperatorIcon name="arrow" /></a>
            <p class="trade-explainer">Review and submit at Robinhood · {{ observation.account.crypto }}</p>
            <dl><div><dt>Available to sell</dt><dd>{{ detail.sellable_quantity }} <small>{{ detail.asset }}</small></dd></div><div><dt>Reserved for sells</dt><dd>{{ detail.quantity_in_open_sells }} <small>{{ detail.asset }}</small></dd></div><div><dt>Cost basis</dt><dd>{{ money(detail.cost_basis) }}</dd></div><div><dt>Bid / ask</dt><dd>{{ money(detail.quote?.bid) }} <span>/</span> {{ money(detail.quote?.ask) }}</dd></div><div><dt>Price source</dt><dd>Robinhood <small v-if="detail.quote">· {{ elapsed(Math.max(0, now - detail.quote.quoted_ms)) }} ago</small></dd></div></dl><p v-if="detail.quote && !detail.quote.book_valid" class="quote-note">Broker bid/ask is crossed. Mark and P&amp;L are indicative.</p><details class="broker-permissions"><summary>Account permissions</summary><div><span>Robinhood approvals</span><strong>{{ permissions ? permissions.approval_required ? 'Required' : 'Off' : 'Unknown' }}</strong></div><div><span>Options account access</span><strong>{{ permissions ? permissions.options_level === 'none' ? 'Not approved' : permissions.options_level === 'option_level_2' ? 'Level 2' : 'Level 3' : 'Unknown' }}</strong></div><p v-if="permissions && permissions.options_level !== 'none'">Options available via MCP · no active options strategy</p></details></template>
          <div v-else class="detail-empty">Select a holding to inspect its availability and pricing.</div>
        </aside>
      </div>
      <footer class="account-footer"><span :class="{ aging: stale }"><i></i>{{ stale ? 'Last known account read' : 'Account read' }} <time :datetime="observedAt" :title="observedLabel">{{ elapsed(age) }} ago</time></span><span>{{ observedLabel }}</span><span v-if="connected">Auto sync {{ (sync.interval_ms ?? 30000) / 1000 }}s<span v-if="nextRead"> · next in {{ nextRead }}</span></span><span v-else>Automatic sync disconnected</span></footer>
    </template>
    <div v-else class="no-account"><span aria-hidden="true">◈</span><h3>Your portfolio, in one place</h3><p>Connect Robinhood to load your real holdings and balances.</p></div>
  </section>
</template>

<style scoped>
